export default function install(app){const root=app.getMount('inventory-indicators');const row=document.createElement('div');Object.assign(row.style,{display:'flex',flexWrap:'wrap',gap:'12px',alignItems:'center'});const text=document.createElement('span');text.textContent='Resumen de contenido accesible · pulsa Actualizar';const button=document.createElement('button');button.textContent='Actualizar resumen';Object.assign(button.style,{padding:'7px 10px',border:'1px solid #cbd5e1',borderRadius:'7px',background:'white',color:'#1769aa',cursor:'pointer'});row.append(text,button);root.replaceChildren(row);let disposed=false,busy=false;async function refresh(){if(busy)return;busy=true;button.disabled=true;text.textContent='Consultando…';try{const Portal=await app.import('esri/portal/Portal');const p=new Portal({url:app.portalUrl});await p.load();const org=p.user?.orgId||p.id;if(!org)throw new Error('No se pudo identificar la organización');const types=[null,'Web Map','Dashboard'];const results=await Promise.all(types.map(type=>p.queryItems({query:`orgid:${org}`+(type?` AND type:"${type}"`:''),num:1,start:1})));const values=results.map(r=>r.total);if(!disposed)text.textContent=`Contenido accesible: ${values[0].toLocaleString('es-ES')} · Mapas web: ${values[1].toLocaleString('es-ES')} · Dashboards: ${values[2].toLocaleString('es-ES')}`;return{total:values[0],webMaps:values[1],dashboards:values[2]};}catch(e){if(!disposed)text.textContent=`No se pudo actualizar: ${e.message}`;return{error:e.message};}finally{busy=false;if(!disposed)button.disabled=false;}}button.addEventListener('click',refresh);const action=app.actions.register('refresh-inventory-summary',refresh);app.onCleanup(()=>{disposed=true;button.removeEventListener('click',refresh);action.remove();root.replaceChildren();});}